def map_input_to_output_blocks(inp, out):
    inp_h, inp_w = len(inp), len(inp[0])
    out_h, out_w = len(out), len(out[0])

    blocks = {}
    for i in range(inp_h):
        for j in range(inp_w):
            input_val = inp[i][j]
            out_block = tuple(out[3*i + dr][2*j + dc] for dr in range(3) for dc in range(2))
            blocks[(i, j)] = out_block  # Block ID by position

    print("Unique input positions with same output block:")
    block_positions = {}
    for pos, block in blocks.items():
        if tuple(block) not in block_positions:
            block_positions[tuple(block)] = []
        block_positions[tuple(block)].append(pos)

    for block, pos_list in sorted(block_positions.items()):
        print(f"  Block: {list(block)} → positions: {pos_list}")

    # Now map input VALUES to these blocks
    print("\n\nHow input VALUES map to blocks:")
    val_to_positions = {}
    for pos, block in blocks.items():
        i, j = pos
        input_val = inp[i][j]
        if input_val not in val_to_positions:
            val_to_positions[input_val] = set()
        val_to_positions[input_val].add(tuple(block))

    for val, block_set in sorted(val_to_positions.items()):
        print(f"Input value {val} → blocks:", block_set)
